-- Comprobación: cuántos quedaron con costo y cuál es el margen promedio
SELECT count(*) FILTER (WHERE costo_compra > 0) AS con_costo, count(*) AS total,
       round(avg((precio - costo_compra) / precio) * 100, 1) AS margen_pct
  FROM materiales WHERE precio > 0;
